server.createContext("/books/1", exchange -> {
    String method = exchange.getRequestMethod();
    if (method.equals("PUT")) {
        // cale cialo requestu ZASTEPUJE caly zasob - brakujace pola "znikaja"
        respondJson(exchange, 200, "{\"id\":1,\"title\":\"Zaktualizowany tytul\"}");
    } else if (method.equals("PATCH")) {
        // TYLKO wskazane pole ulega zmianie, reszta zasobu zostaje bez zmian
        respondJson(exchange, 200, "{\"id\":1,\"title\":\"Java\",\"price\":39.90}");
    } else if (method.equals("DELETE")) {
        exchange.sendResponseHeaders(204, -1); // brak ciala odpowiedzi
    }
});

